// Typical Hierarchy Levels (Speed/Cost -> Capacity)
// CPU Access Time
L0: Registers (Fastest, Smallest)
L1: Primary Cache (SRAM, few cycles)
L2: Secondary Cache (SRAM, 10-20 cycles)
L3: Shared Cache (SRAM, 30-50 cycles)
Main Memory: DRAM (100+ cycles)
Secondary Storage: SSD/NVMe (Microseconds)
Tertiary Storage: HDD/Tape (Milliseconds)

// Locality of Reference (Caches exploit this)
// Temporal: Reusing recently accessed data.
// Spatial: Accessing data near recently accessed data.

// Cache Line Size (Typical)
#define CACHE_LINE_BYTES 64

// Example: Spatial Locality Optimization (C/C++)
// Row-major access is faster in C/C++ (better spatial locality)
int matrix[N][M];
// Fast
for (i=0; i<N; i++) for (j=0; j<M; j++) sum += matrix[i][j];
// Slow (cache misses)
for (j=0; j<M; j++) for (i=0; i<N; i++) sum += matrix[i][j];
